package com.wander.identity.application.input;

/** Names of the JSON input fields of the Identity API (the contract, matching {@code web/src/api.ts}) and the evidence type values. */
public final class IdentityFields {

    /** Id of the recovery attempt. */
    public static final String ATTEMPT_ID = "attemptId";

    /** Session secret generated by the device itself. */
    public static final String SESSION_TOKEN = "sessionToken";

    /** Recovery code typed by the user. */
    public static final String CODE = "code";

    /** Replacement code typed again by the user. */
    public static final String REPLACEMENT_CODE = "replacementCode";

    /** Device pairing code. */
    public static final String PAIRING_CODE = "pairingCode";

    /** Re-authentication approval code. */
    public static final String APPROVAL_CODE = "approvalCode";

    /** Id of the pending replacement code. */
    public static final String PENDING_ID = "pendingId";

    /** Re-authentication evidence. */
    public static final String EVIDENCE = "evidence";

    /** Type of the evidence. */
    public static final String EVIDENCE_TYPE = "type";

    /** Id of the approval request. */
    public static final String REQUEST_ID = "requestId";

    /** Action that needs re-authentication. */
    public static final String OPERATION = "operation";

    /** Skip creating a recovery code when the identity is created. */
    public static final String SKIP_RECOVERY_CODE = "skipRecoveryCode";

    /** Matching number chosen by the approver. */
    public static final String NUMBER = "number";

    /** Device name declared by the device itself. */
    public static final String DEVICE_NAME = "deviceName";

    /** Evidence type: present the current recovery code. */
    public static final String EVIDENCE_TYPE_CODE = "code";

    /** Evidence type: approval from another device. */
    public static final String EVIDENCE_TYPE_APPROVAL = "approval";

    private IdentityFields() {
    }
}
